CREATE TABLE office_objects(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,local_id uuid NOT NULL,object_kind text NOT NULL,identity_key text NOT NULL,marker text NOT NULL,remote_id text,remote_url text,remote_revision text,synced_version integer NOT NULL DEFAULT 0,desired_version integer NOT NULL,desired_hash text NOT NULL,status text NOT NULL,last_error text,attempted_at timestamptz,lease_expires_at timestamptz,UNIQUE(run_id,object_kind,identity_key),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE office_sync_cursors(project_id uuid NOT NULL,run_id uuid NOT NULL,sequence bigint NOT NULL DEFAULT 0,PRIMARY KEY(project_id,run_id),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
